// P1 T0 -- Estate Health KPI row  [multistat]
//
// WHY ONE TILE INSTEAD OF FOUR. The import rendered but the four `stat` tiles
// errored with "Current tile size (4, 4) is smaller than the minimum supported
// tile size (9, 7)". On a 16-column grid a 9-wide minimum means at most ONE stat
// per row -- four of them would cost 28 rows of vertical space for four numbers.
// `multistat` is the visual designed for exactly this: several values in a grid
// of slots, from one query, in one tile. Four KPIs, one 16x7 tile.
//
// Every branch must project the SAME two columns for the union to be well-typed,
// and every Value is todouble() so a count and a percentile can share a column.
let as_of = _endTime;
let dark_minutes = 20;
let gen_dow = (toint(dayofweek(as_of) / 1d) + 6) % 7;
let tod = as_of - startofday(as_of);
let open_now = materialize(
    fn_store_open_sessions()
    | where day_of_week == gen_dow
    | where tod between (open_ts .. close_ts)
    | distinct store_id);
union
  // "Terminals reporting", NOT "terminals live". The first build asked
  // mv_terminal_last_seen for terminals seen within the last 20 minutes and
  // rendered **2 of 1,500** at the 00:35 reference time -- technically correct and
  // badly misleading. Every terminal's final backfill ping lands between 23:45 and
  // 00:20:23, so a 20-minute recency test is only meaningful within 20 minutes of
  // the data's true last ingest; a minute later it collapses to near zero.
  // Distinct terminals with ANY telemetry in the reference window is well-defined
  // for any window the operator picks. Paired with "Dark right now" it tells the
  // real story: 1,500 reporting, N currently overdue during trading hours.
  (telemetry_curated
   | where trusted_time between (_startTime .. as_of)
   | summarize Value = todouble(dcount(terminal_id))
   | extend ord = 1, Metric = 'Terminals reporting'
   | project ord, Metric, Value),
  (fn_reflex3_terminal_dark(20, as_of)
   | summarize Value = todouble(count())
   | extend ord = 2, Metric = 'Dark right now'
   | project ord, Metric, Value),
  (open_now
   | summarize Value = todouble(count())
   | extend ord = 3, Metric = 'Stores trading'
   | project ord, Metric, Value),
  (telemetry_curated
   | where trusted_time between (_startTime .. as_of)
   | summarize Value = round(percentile(clock_skew_seconds, 95), 1)
   | extend ord = 4, Metric = 'Ingest lag p95 (s)'
   | project ord, Metric, Value)
| order by ord asc
| project Metric, Value

// P1 T5 -- Terminal status by merchant tier  [column]
// dim_estate carries merchant_tier (one row per terminal, denormalized).
// It deliberately carries NO store_archetype -- the generator never persists one.
let as_of = _endTime;
let dark_minutes = 20;
mv_terminal_last_seen
| extend minutes_dark = datetime_diff('minute', as_of, trusted_time)
| extend Status = iff(minutes_dark >= dark_minutes, 'Silent', 'Live')
| join kind=inner (dim_estate | project terminal_id, merchant_tier) on terminal_id
| summarize Terminals = count() by merchant_tier, Status
| order by merchant_tier asc, Status asc

// P1 T6 -- Estate composition  [pie]
// Three buckets, matching the mockup. The distinction that matters: a silent
// terminal whose store is CLOSED is "Live, off-hours", not "Dark" -- that is
// reflex 3's own definition, and reporting it any other way would inflate the
// outage count every night.
let as_of = _endTime;
let dark_minutes = 20;
let gen_dow = (toint(dayofweek(as_of) / 1d) + 6) % 7;
let tod = as_of - startofday(as_of);
let open_now = fn_store_open_sessions()
    | where day_of_week == gen_dow
    | where tod between (open_ts .. close_ts)
    | distinct store_id;
mv_terminal_last_seen
| extend minutes_dark = datetime_diff('minute', as_of, trusted_time)
| extend trading = store_id in (open_now)
| extend Bucket = case(
    trading and minutes_dark >= dark_minutes, 'Dark / overdue',
    trading, 'Live & trading',
    'Live, off-hours')
| summarize Terminals = count() by Bucket
| order by Terminals desc

// P1 T7 -- Reflex 3 terminal-dark feed  [table]
// NOTE, recorded rather than quietly substituted: the mockup shows merchant
// display names ("Nasi Kandar Meridian"). The generator persists no merchant
// name -- stg_dim_merchant is (merchant_id, merchant_tier, mcc, mcc_description).
// mcc_description is the closest real attribute and is used instead.
let as_of = _endTime;
fn_reflex3_terminal_dark(20, as_of)
| join kind=leftouter (dim_estate | project terminal_id, merchant_tier, mcc_description) on terminal_id
| project Terminal = terminal_id,
          Store = store_id,
          Merchant = merchant_id,
          Tier = merchant_tier,
          Trade = mcc_description,
          ['Last seen'] = last_seen,
          ['Dark for (min)'] = minutes_dark
| order by ['Dark for (min)'] desc
| take 200

// P2 T0 -- Fraud Watch KPI row  [multistat]
// Same consolidation as page 1's KPI row, and for the same reason -- see that
// file's header for the minimum-tile-size finding.
//
// The two rate KPIs read a single materialized 15-minute slice, so "auths/sec"
// and "decline rate now" cannot be computed over different populations. The two
// firing counts read the persisted `alerts_v2` table, per the implementation guide,
// so this page and the exported E2 evidence cannot disagree.
// ROUNDING, corrected 2026-08-19. One decimal place renders ANY window holding fewer than
// 45 auths in 15 minutes as '0.0' -- indistinguishable from a broken tile. The reference
// window's quiet 15 minutes is exactly that case, and it was read as an empty tile before
// the arithmetic was checked. Two decimals; the honest small number, not a zero.
let as_of = _endTime;
let win = 15m;
let recent = materialize(
    auth_curated
    | where event_type == 'auth'
    | where trusted_time between (as_of - win .. as_of));
union
  (recent
   | summarize c = count()
   | extend ord = 1, Metric = 'Auths / sec', Value = round(todouble(c) / 900.0, 2)
   | project ord, Metric, Value),
  (recent
   | summarize d = countif(auth_result == 'declined'), t = count()
   | extend ord = 2, Metric = 'Decline rate now (%)',
            Value = round(100.0 * todouble(d) / todouble(max_of(t, 1)), 1)
   | project ord, Metric, Value),
  (alerts_v2
   | where reflex_type == 'card_testing_burst'
   | where window_start between (_startTime .. _endTime)
   | summarize Value = todouble(count())
   | extend ord = 3, Metric = 'Reflex 1 firings'
   | project ord, Metric, Value),
  (alerts_v2
   | where reflex_type == 'terminal_compromise'
   | where window_start between (_startTime .. _endTime)
   | summarize Value = todouble(count())
   | extend ord = 4, Metric = 'Reflex 2 firings'
   | project ord, Metric, Value)
| order by ord asc
| project Metric, Value

// P2 T5 -- Decline rate, trailing window  [line]
// CORRECTION to the implementation guide, recorded not silently applied: the
// guide asks for 1-minute grain from mv_terminal_activity_5min. That MV buckets
// at 5 minutes -- 1-minute grain cannot be recovered from it. Reading
// auth_curated directly would give 1-minute grain but discards the MV, which
// exists precisely so this page is cheap. The MV is used at its true grain.
mv_terminal_activity_5min
| where bucket_5min between (_startTime .. _endTime)
| summarize auths = sum(auth_count), declines = sum(decline_count) by bucket_5min
| where auths > 0
| project bucket_5min, ['Decline rate %'] = round(100.0 * todouble(declines) / todouble(auths), 2)
| order by bucket_5min asc

// P2 T6 -- Top at-risk terminals  [bar]
// Ranked on decline rate over the reference window, with a 20-auth floor so a
// terminal that declined its only transaction cannot take the top slot -- the
// small-denominator trap that makes most "top N by rate" visuals meaningless.
mv_terminal_activity_5min
| where bucket_5min between (_startTime .. _endTime)
| summarize auths = sum(auth_count), declines = sum(decline_count) by terminal_id
| where auths >= 20
| extend ['Decline rate'] = round(todouble(declines) / todouble(auths), 3)
| top 10 by ['Decline rate'] desc
| project terminal_id, ['Decline rate']

// P2 T7 -- Live alert feed  [table]
// Ordered by window_start, deliberately. The implementation guide says "sorted
// desc by fired_at"; every backfill-seeded row in `alerts_v2` carries the identical
// constant fired_at = datetime(2026-08-17) written by
// 11_activator_reflex_alerts.kql, so fired_at cannot order anything. window_start
// is when the signal actually occurred. Recorded in Gate_Check_Results.md.
alerts_v2
| where reflex_type in ('card_testing_burst', 'terminal_compromise')
| where window_start between (_startTime .. _endTime)
| order by window_start desc
| project Signalled = window_start,
          Reflex = reflex_type,
          Terminal = entity_id,
          Store = store_id,
          Merchant = merchant_id,
          Signal = round(signal_value, 3),
          Threshold = round(threshold_value, 3),
          Cohort = maturity_cohort
| take 200

// P3 T1 -- Approval rate by issuer, with anomaly band  [anomalychart]
// The exit-criterion tile: reflex 4 must decompose each issuer against ITS OWN
// baseline, not a fixed threshold. sigma = 2.5 and step = 1h are the same
// parameters fn_reflex4_issuer_degradation uses, so this chart and the reflex
// that writes to `alerts_v2` cannot drift apart.
// default = double(null) leaves an hour with no traffic as a GAP, not as a 0%
// approval rate -- a zero here would be a fabricated outage.
let as_of = _endTime;
let win_start = _startTime;
mv_issuer_baseline
| where hour_bucket between (win_start .. as_of)
| extend approval_rate = todouble(approved) / todouble(max_of(total, 1))
| make-series ApprovalRate = avg(approval_rate) default = double(null)
    on hour_bucket from win_start to as_of step 1h by issuer_bin
| extend (anomalies, score, baseline) = series_decompose_anomalies(ApprovalRate, 2.5)
| project issuer_bin, hour_bucket, ApprovalRate, baseline, anomalies

// P3 T2 -- Issuer BIN health by hour of day  [heatmap]
// Column types are deliberate. The RTD heatmap requires three columns and, when
// x is a string, y must also be a string -- so hour-of-day is emitted as a
// zero-padded "HH:00" label rather than an int. Value is the numeric field.
mv_issuer_baseline
| where hour_bucket between (_startTime .. _endTime)
| extend hod = hourofday(hour_bucket)
| summarize approved_sum = sum(approved), total_sum = sum(total) by issuer_bin, hod
| where total_sum > 0
| project ['Issuer BIN'] = issuer_bin,
          ['Hour'] = strcat(iff(hod < 10, '0', ''), tostring(hod), ':00'),
          ['Approval %'] = round(100.0 * todouble(approved_sum) / todouble(total_sum), 1)
| order by ['Issuer BIN'] asc, ['Hour'] asc
